"""Explain default fences and acquire/release/full wrappers step by step."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1625': ('학교마다 쓰는 안내 규칙이 있으면 그것을 쓰고, 따로 정한 규칙이 없으면 공통 규칙을 쓰는 것과 비슷해요. 여기서는 CPU별 규칙과 기본 규칙을 골라요.', '장벽의 기본 연결과 CPU별 재정의를 구별합니다.', 'acquire → after, release → before, pre full → before, post full → after를 쓰고, 각 줄 앞에 별도 정의가 없을 때라고 붙이세요.', ['fence는 메모리 접근의 순서 관계를 보강하는 장벽이에요. before는 앞, after는 뒤라는 뜻이에요. 어떤 원자 연산을 기준으로 앞뒤 중 어디에 놓이는지 함께 읽어야 해요.', '공통 atomic.h는 __atomic_acquire_fence의 기본 이름을 smp_mb__after_atomic으로 연결해요. acquire 도우미에서는 실제 원자 연산 뒤에 이 장벽을 호출해요.', '__atomic_release_fence는 smp_mb__before_atomic으로 연결해요. release 도우미는 장벽을 먼저 거친 다음 원자 연산을 실행해요. 이름이 비슷해도 acquire와 release의 위치는 달라요.', 'full 도우미는 앞과 뒤 두 자리에 장벽을 둬요. __atomic_pre_full_fence는 before_atomic, __atomic_post_full_fence는 after_atomic에 기본 연결돼요. pre는 전, post는 후라고 읽으면 기억하기 쉬워요.', '각 기본 연결 위에는 #ifndef가 있어요. 해당 이름이 아직 정의되지 않았다면 아래 정의를 쓰라는 전처리 조건이에요. CPU별 헤더가 이미 정의했다면 그 정의를 보존해요. 실행 중 매번 CPU를 물어보고 고르는 if 문이 아니에요.', '어떤 CPU에서는 바탕 relaxed 연산이 이미 강한 순서를 제공해서 추가 장벽이 필요 없을 수 있어요. 따라서 공통 코드의 장벽 이름만 세어 모든 CPU에서 비용이 같다고 말할 수 없어요. 원문의 after_spinlock 관련 주석도 CPU별 구현자가 다른 순서 규칙과의 연결을 살펴보라는 안내예요.'], [('별도 정의가 없을 때 release 장벽은 어느 이름에 연결되나요?', ['smp_mb__after_atomic, 즉 연산 뒤 장벽이에요', 'smp_mb__before_atomic, 즉 연산 앞 장벽이에요'], '정답은 두 번째예요. release의 기본 연결은 before_atomic이고 release 도우미도 연산 앞에 장벽을 놓아요. after_atomic은 acquire와 post full의 기본 연결이에요.'), ('CPU별 헤더가 acquire 장벽을 이미 정의했어요. 공통 기본 정의가 그것을 덮어쓰나요?', ['아니요. #ifndef가 있어서 이미 있는 정의를 보존해요', '네. 나중에 읽는 공통 헤더가 무조건 덮어써요'], '정답은 첫 번째예요. #ifndef는 아직 정의되지 않았을 때만 아래 정의를 사용하라는 뜻이에요. 파일을 나중에 읽는다는 이유만으로 이 조건이 사라지지 않아요.')]), 'os1626': ('계산기에서 나온 답을 쪽지에 적고, 다음 절차를 마친 뒤 그 쪽지를 건네준다고 생각해 보세요. 답을 다시 계산하지 않고 보관했다가 돌려줘요.', 'acquire 보강의 결과 저장과 실행 횟수를 이해합니다.', '연산 결과가 7이라고 가정하고 연산 → __ret에 7 저장 → acquire 장벽 → 7 반환을 그리세요.', ['__atomic_op_acquire는 원자 연산에 acquire 순서를 보강하는 내부 매크로예요. 매크로는 코드를 번역하기 전에 이름을 정해 둔 코드로 바꾸는 규칙이에요. op는 연산 이름, args는 전달할 인자들이에요.', 'op##_relaxed의 ##는 이름 조각을 붙이는 표시예요. op가 demo라면 demo_relaxed라는 이름을 만들어요. 이 이름 붙이기 자체가 연산을 실행하는 것은 아니에요.', '첫 문장의 typeof는 결과의 자료형을 알아보는 데 쓰여요. 자료형은 정수인지 참·거짓인지처럼 값의 종류를 말해요. 그 형식에 맞는 __ret라는 임시 칸을 만들고, 실제 relaxed 연산의 결과를 넣어요.', '그 다음 __atomic_acquire_fence를 호출해 순서를 보강해요. 마지막의 __ret는 보관한 결과를 밖으로 전달해요. 연산이 7을 돌려줬다면 장벽 뒤에도 결과는 7이에요. 장벽의 결과 숫자를 대신 반환하는 것이 아니에요.', '({ ... })는 여러 문장을 실행하고 마지막 표현식의 값을 사용하는 GNU C 확장 문법이에요. 보통의 정수·bool 결과와 고정된 자료형 인자에서는 typeof 안의 연산을 실제 실행하지 않아요. 따라서 글자에 연산 이름이 두 번 보여도 실제 호출과 그 인자 평가는 한 번이에요.', '이 설명을 모든 typeof 사용에 무조건 적용하면 안 돼요. 실행 중 크기가 정해지는 배열과 관련된 타입에는 별도 규칙이 있어요. 또 이 도우미는 결과를 변수에 담으므로 결과가 없는 void 연산을 같은 방식으로 넣을 수 없어요. 우선 여기의 정수·참거짓 결과를 따라가세요.'], [('acquire 도우미가 마지막에 돌려주는 값은 어디에서 왔나요?', ['장벽이 새로 계산해 준 숫자예요', 'relaxed 연산의 결과를 담아 둔 __ret예요'], '정답은 두 번째예요. 연산 결과를 __ret에 저장하고 장벽을 지난 뒤 그 값을 돌려줘요. 장벽은 결과를 계산하는 도구가 아니라 순서 관계를 보강하는 도구예요.'), ('일반적인 정수 결과와 고정된 타입 인자를 쓰는 이 도우미는 typeof 때문에 연산을 두 번 실행하나요?', ['아니요. 이 경우 실제 연산과 인자 평가는 한 번이에요', '네. 코드에 이름이 두 번 있으므로 반드시 두 번 실행해요'], '정답은 첫 번째예요. 이 경우 typeof는 타입을 알아보고, 실제 실행은 __ret를 초기화하는 오른쪽 호출에서 이뤄져요. 다만 모든 종류의 typeof 식이 무조건 실행되지 않는다고 넓혀 외우면 안 돼요.')]), 'os1627': ('안내문을 먼저 준비한 뒤 준비 완료 표시를 붙이는 순서를 생각해 보세요. release 도우미는 연산 앞에서 필요한 순서 약속을 보강해요.', 'release 도우미의 앞 장벽과 값이 없는 연산을 이해합니다.', 'release 장벽 → relaxed 연산을 그리세요. 결과가 5인 경우에는 5 반환, void인 경우에는 반환 숫자 없음이라고 적으세요.', ['__atomic_op_release의 첫 작업은 __atomic_release_fence를 호출하는 것이에요. fence는 다른 메모리 접근과의 순서를 보강하는 장벽이에요. 이 코드에서는 실제 relaxed 연산보다 앞에 있어요.', '그 다음 op##_relaxed(args)를 실행해요. ##는 이름을 붙이는 표시이므로 op가 demo이면 demo_relaxed라는 이름이 돼요. args는 그 연산에 넘길 값이나 주소 같은 인자들이에요.', '이 도우미는 GNU C의 ({ ... }) 형태예요. 그 안에서 마지막에 실행한 표현식이 값이 있으면 그 값이 전체 표현식의 결과가 돼요. relaxed 연산이 5를 돌려주면 바깥에서도 5를 받아요.', 'acquire 도우미와 달리 여기에는 __ret라는 임시 결과 변수가 없어요. 연산 뒤에 따로 장벽을 수행할 필요 없이 마지막 호출의 결과를 그대로 사용할 수 있기 때문이에요. 본문의 앞뒤 순서를 보고 구별하세요.', 'void는 함수가 결과 값을 돌려주지 않는다는 뜻이에요. 값을 설정만 하고 반환 숫자가 없는 연산도 이 release 도우미의 코드 형태로 감쌀 수 있어요. 일을 안 한다는 뜻도, 숫자 0을 반환한다는 뜻도 아니에요.', '예를 들어 어떤 void 설정 연산이 숫자 칸을 3으로 바꾸면 칸의 값은 3이지만 호출 결과로 받은 숫자는 없어요. 내부 도우미의 문법이 이런 연산을 허용한다고 모든 공개 API에 원하는 연산을 끼워 넣어도 된다는 뜻은 아니에요. 실제 API의 타입과 사용 조건도 지켜야 해요.'], [('release 도우미는 장벽과 relaxed 연산 중 무엇을 먼저 실행하나요?', ['연산을 먼저 하고 뒤에서 acquire 장벽을 실행해요', 'release 장벽을 먼저 하고 relaxed 연산을 실행해요'], '정답은 두 번째예요. 본문의 첫 문장이 release 장벽이고 마지막 문장이 실제 연산이에요. acquire 도우미의 뒤 장벽과 혼동하지 마세요.'), ('이 release 도우미의 코드 형태는 값을 돌려주지 않는 void 설정 연산도 감쌀 수 있나요?', ['네. 마지막 호출이 void여도 이 형태로 사용할 수 있어요', '아니요. 모든 도우미가 반드시 __ret 변수에 값을 담아요'], '정답은 첫 번째예요. release 본문은 결과 변수를 만들지 않고 마지막에 연산을 호출해요. void라면 반환 숫자가 없을 뿐이며 설정 작업은 실행돼요. acquire와 full의 결과 변수 구조를 여기에 그대로 적용하면 안 돼요.')]), 'os1628': ('계산 앞뒤에 순서 확인 절차를 두고 계산 결과는 따로 보관한다고 생각해 보세요. 확인 절차가 있다고 계산 중간에 다른 사람이 끼어들 수 없는 것은 아니에요.', 'full 보강의 앞뒤 장벽과 기반 연산의 원자성을 구별합니다.', 'pre 장벽 → 연산 결과를 __ret에 저장 → post 장벽 → __ret 반환을 그리세요. 원자성은 바탕 연산이 제공한다고 옆에 적으세요.', ['__atomic_op_fence는 full 순서를 보강하는 내부 도우미예요. pre는 앞, post는 뒤를 뜻해요. 바탕이 되는 원자 연산의 앞뒤에 필요한 메모리 순서 장벽을 놓는 구조예요.', '먼저 typeof로 결과의 자료형에 맞는 __ret 칸을 선언해요. 선언은 칸을 준비하는 것이고 아직 연산 결과를 넣는 단계가 아니에요. 그 다음 __atomic_pre_full_fence를 호출해요.', '앞 장벽을 거친 다음 relaxed 연산을 실제 실행하고 결과를 __ret에 저장해요. 이어서 __atomic_post_full_fence를 호출하고 마지막에 __ret를 돌려줘요. 따라서 계산과 결과 저장은 두 장벽 사이에 있어요.', '정수 결과 7을 받았다면 7을 보관했다가 반환해요. 비교 연산의 bool 결과라면 참 또는 거짓을 보존해요. bool은 참·거짓을 나타내는 자료형이에요. 장벽을 거쳤다고 결과의 뜻이 바뀌지 않아요.', '원자성은 지정된 갱신이 중간에 쪼개져 관찰되지 않도록 하는 성질이에요. 여기서는 바탕 relaxed 원자 연산이 그 성질을 제공해야 해요. relaxed는 다른 접근의 순서 약속이 약하다는 뜻이지, 원자성이 없다는 뜻이 아니에요.', '일반 읽기와 쓰기 앞뒤에 장벽만 붙인다고 원자적 증가가 되지는 않아요. 두 사람이 각각 0을 읽고 1을 저장하면 두 번 더했어도 최종 값이 1이 될 수 있어요. 장벽은 두 사람의 읽기·계산·쓰기 전체를 하나씩 실행하게 하는 잠금이 아니기 때문이에요.'], [('full 도우미는 연산 결과를 __ret에 언제 저장하나요?', ['앞뒤 장벽을 모두 실행하기 전에 저장해요', 'pre 장벽을 지난 뒤, post 장벽을 실행하기 전에 저장해요'], '정답은 두 번째예요. 원문의 흐름은 pre → __ret에 연산 결과 저장 → post → 반환이에요. 칸을 먼저 선언하는 것과 실제 결과를 저장하는 것은 다른 단계예요.'), ('일반 읽기와 쓰기의 앞뒤에 장벽 두 개를 붙이면 자동으로 원자적 증가가 되나요?', ['아니요. 원자적 갱신을 보장하는 바탕 연산 등이 필요해요', '네. 장벽 두 개가 모든 작업 묶음을 원자적으로 바꿔요'], '정답은 첫 번째예요. 두 실행 흐름이 모두 0을 읽고 각각 1을 쓰는 상황을 장벽만으로 막지는 못해요. 접근의 순서 보강과 갱신의 원자성은 서로 다른 약속이에요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_402.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
